// The pure cores come from src/tools_core63.js (generated by gen_tools_core.py from tool-gap-2026-10/newtools/metal-core-63a.js,
// cone-core-63a.js, hinge-core-63a.js, nutrition-core-63b.js, ergo-core-63b.js) — one source of truth with the /tools/ pages.
// Stateless: no D1/R2, no fetch.
import { MGDMetal as M, MGDCone as C, MGDHinge as H, MGDNutrition as N, MGDErgo as E } from "./tools_core63.js";

const T = "https://madegooddesigns.com/tools";
const ok = (text, structuredContent) => ({ content: [{ type: "text", text }], structuredContent });
const err = (text) => ({ content: [{ type: "text", text }], isError: true });
const str = (x, max) => (typeof x === "string" ? x : x == null ? "" : String(x)).slice(0, max);
const RO = (title) => ({ title, readOnlyHint: true, destructiveHint: false, openWorldHint: false });
const fence = (lang, s) => "```" + lang + "\n" + String(s).replace(/\n$/, "") + "\n```";
const OUT_CAP = 120 * 1024;
const r3 = (x) => Math.round(x * 1000) / 1000;
const num = (v) => (v === undefined || v === null || v === "" ? undefined : Number(v));
const unitOf = (u) => (u === "in" ? "in" : "mm");
const FMT = (a, dflt) => (["svg", "dxf", "none"].includes(a) ? a : dflt);
const MATS = ["steel", "galvanized", "stainless", "aluminum", "copper", "awg"];

