export const NEXT63 = {
  get_sheet_metal_gauge: "Next step: calc_sheet_metal_bend with this thickness for the flat length of a bent part.",
  calc_sheet_metal_bend: "Next step: open the page link for a multi-flange drawing and a PDF of the working; get_sheet_metal_gauge for gauge thicknesses.",
  make_cone_pattern: "Next step: open the page link to print the pattern true size over several A4/Letter sheets (tiled PDF with alignment marks).",
  make_living_hinge: "Next step: test-cut a small sample first; the bend estimate is approximate and depends on the material batch.",
};

function file(lines, sc, fmt, svgFn, dxfFn, svgLabel, dxfLabel) {
  if (fmt === "none") return;
  const f = fmt === "svg" ? svgFn() : dxfFn();
  if (f.length > OUT_CAP) { lines.push(`The ${fmt.toUpperCase()} is ${Math.round(f.length / 1024)} KB: too big to return inline; download it from the page.`); return; }
  lines.push(fmt === "svg" ? svgLabel : dxfLabel, fence(fmt, f)); sc[fmt] = f;
}

function gauge(a) {
  const material = str(a.material, 20).trim().toLowerCase() || "steel", unit = unitOf(a.unit);
  const page = `${T}/sheet-metal-gauge-chart/`;
  let r, sc;
  if (num(a.thickness) !== undefined) {
    r = M.nearest({ material, thickness: num(a.thickness), unit });
    if (!r || !r.ok) return err((r && r.error) || `Unknown material "${material}". Use one of: ${MATS.join(", ")}.`);
    const b = r.best;
    const lines = [`**Nearest ${b.name} gauge to ${r3(r.thickness_mm)} mm (${r3(r.thickness_in)} in): ${b.gauge} ga** = ${b.inch} in / ${r3(b.mm)} mm (${b.diff_pct >= 0 ? "+" : ""}${r3(b.diff_pct)}%).`];
    if (r.thinner) lines.push(`Next thinner: ${r.thinner.gauge} ga = ${r.thinner.inch} in / ${r3(r.thinner.mm)} mm.`);
    if (r.thicker) lines.push(`Next thicker: ${r.thicker.gauge} ga = ${r.thicker.inch} in / ${r3(r.thicker.mm)} mm.`);
    if (r.outOfRange) lines.push("Note: the thickness is outside this gauge table's range.");
    sc = { mode: "nearest", material: b.material, thickness_mm: r.thickness_mm, thickness_in: r.thickness_in, best: b, thinner: r.thinner || null, thicker: r.thicker || null, page };
    r = { ...b, lines };
  } else {
    if (num(a.gauge) === undefined) return err("Give a gauge number, or a measured thickness for the nearest gauge.");
    r = M.lookup({ material, gauge: num(a.gauge) });
    if (!r || !r.ok) return err((r && r.error) || `No gauge ${a.gauge} for "${material}". Materials: ${MATS.join(", ")}.`);
    r.lines = [`**${r.gauge} gauge ${r.name}: ${r.inch} in = ${r3(r.mm)} mm**` + (r.kg_m2 ? `, ${r.kg_m2} kg/m² (${r.lb_ft2} lb/ft²).` : ".")];
    sc = { mode: "lookup", ...r, lines: undefined, page };
  }
  const lines = r.lines;
  if (num(a.length) > 0 && num(a.width) > 0 && r.kg_m2) {
    const w = M.sheetWeight({ material: r.material || material, thickness_mm: r.mm, length: num(a.length), width: num(a.width), qty: 1, unit });
    if (w && w.ok !== false) { const kg = w.kg != null ? w.kg : w.total_kg; if (kg != null) { lines.push(`Sheet ${num(a.length)} × ${num(a.width)} ${unit}: about ${r3(kg)} kg (${r3(kg * 2.20462)} lb).`); sc.sheet_weight_kg = r3(kg); } }
  }
  if (r.source) lines.push(`Source: ${r.source}.`);
  lines.push("Gauge numbers are nominal; mills supply within a tolerance, so measure critical parts. Full charts by material: " + page);
  return ok(lines.join("\n"), sc);
}

function bendTool(a) {
  const unit = unitOf(a.unit), t = num(a.thickness), r = num(a.radius);
  if (!(t > 0) || !(r >= 0)) return err("thickness must be > 0 and radius ≥ 0.");
  const flanges = Array.isArray(a.flanges) ? a.flanges.slice(0, 20).map(Number) : undefined;
  if (flanges && !flanges.every((x) => Number.isFinite(x) && x > 0)) return err("flanges must be positive numbers.");
  const spec = { t, r, angle: num(a.angle) === undefined ? 90 : num(a.angle), material: str(a.material, 20).toLowerCase() || "steel", unit,
    dims: a.dims === "inside" ? "inside" : "outside", width: num(a.width) > 0 ? num(a.width) : undefined };
  if (num(a.k) !== undefined) spec.k = num(a.k); else spec.kMethod = "table";
  if (flanges && flanges.length >= 2) spec.flanges = flanges;
  const b = M.bend(spec);
  if (!b || !b.ok) return err("Could not calculate the bend: " + ((b && (b.error || (b.errors || []).join(" "))) || "check the inputs."));
  const u = b.unit, page = `${T}/bend-allowance-calculator/`;
  const lines = [`**Bend allowance ${r3(b.ba)} ${u}, bend deduction ${r3(b.bd)} ${u}, outside setback ${r3(b.ossb)} ${u}** (T ${b.t}, inside R ${b.r}, ${b.angle}°, K ${r3(b.k)}).`,
    "BA = π/180 × A × (R + K × T); OSSB = tan(A/2) × (R + T); BD = 2 × OSSB − BA."];
  if (b.segments && b.segments.length > 1) {
    lines.push(`Flat length ${r3(b.flat)} ${u} for flanges ${flanges.join(" + ")} ${u} (${b.dims} dimensions; sum ${r3(b.sumL)} − ${b.bends.length} × BD).`);
    lines.push("Bend lines from the left edge: " + b.bends.map((x) => `${r3(x.centre)} ${u}`).join(", ") + ".");
  }
  if (b.warnings && b.warnings.length) lines.push("Note: " + b.warnings.join(" "));
  const sc = { unit: u, t: b.t, r: b.r, angle: b.angle, k: b.k, ba: b.ba, bd: b.bd, ossb: b.ossb, issb: b.issb, flat: b.segments && b.segments.length > 1 ? b.flat : null,
    bends: b.bends || [], segments: b.segments || [], warnings: b.warnings || [], page };
  const fmt = FMT(a.format, "none");
  if (fmt !== "none" && !(b.segments && b.segments.length > 1)) lines.push("(Give at least two flanges to get a flat-pattern file.)");
  else file(lines, sc, fmt, () => M.flatSVG(b, { width: spec.width }), () => M.flatDXF(b, { width: spec.width }), "True-size flat pattern SVG (cut outline, bend lines):", "DXF R12 (layers CUT, BEND, BENDZONE):");
  lines.push("Check the K-factor with a test bend on your brake and material for tight tolerances: " + page);
  return ok(lines.join("\n"), sc);
}

function cone(a) {
  const unit = unitOf(a.unit), d1 = num(a.d1);
  if (!(d1 > 0)) return err("d1 (the larger diameter) must be a positive number.");
  const d2 = num(a.d2) === undefined ? 0 : num(a.d2);
  const spec = { type: d2 === 0 ? "cone" : d2 === d1 ? "cylinder" : "frustum", d1, d2, unit, dims: ["mean", "outside", "inside"].includes(a.dims) ? a.dims : "mean",
    t: num(a.thickness) || 0, seam: num(a.seam) || 0, segments: Math.max(1, Math.min(24, Math.round(num(a.segments) || 1))) };
  if (num(a.height) > 0) spec.h = num(a.height); else if (num(a.slant) > 0) spec.slant = num(a.slant); else return err("Give the height (or the slant height).");
  const p = C.pattern(spec);
  if (!p || !p.ok) return err("Could not make the pattern: " + ((p && (p.error || (p.errors || []).join(" "))) || "check the sizes."));
  const u = unitOf(p.unit), page = `${T}/cone-template/`, name = p.type === "cylinder" ? "Cylinder" : p.type === "cone" ? "Cone" : "Truncated cone (frustum)";
  const lines = [`**${name} flat pattern:** ` + (p.type === "cylinder" ? `rectangle ${r3(p.arcOuter)} × ${r3(p.slant)} ${u}` :
    `outer radius ${r3(p.R1)} ${u}${p.R2 ? `, inner radius ${r3(p.R2)} ${u}` : ""}, sweep ${r3(p.theta)}°, slant height ${r3(p.slant)} ${u}`) + ".",
    `Mean diameters ${r3(p.dm1)} / ${r3(p.dm2)} ${u}, height ${r3(p.h)} ${u}${p.t ? `, thickness ${p.t} ${u}` : ""}${p.seam ? `, seam allowance ${p.seam} ${u}` : ""}.`];
  if (p.segments > 1) lines.push(`${p.segments} identical pieces, each sweeping ${r3(p.thetaPiece)}°.`);
  if (p.chord) lines.push(`Chord of the outer arc ${r3(p.chord)} ${u}; area ${r3(p.area)} ${u}².`);
  if (p.flipped) lines.push("(d2 was larger than d1, so the two were swapped.)");
  if (p.warnings && p.warnings.length) lines.push("Note: " + p.warnings.join(" "));
  const sc = { type: p.type, unit: u, R1: p.R1, R2: p.R2, theta: p.theta, theta_piece: p.thetaPiece, slant: p.slant, height: p.h, dm1: p.dm1, dm2: p.dm2,
    chord: p.chord, area: p.area, segments: p.segments, seam: p.seam, warnings: p.warnings || [], page };
  file(lines, sc, FMT(a.format, "svg"), () => p.svg(), () => p.dxf(), "True-size SVG (cut outline, fold/seam line):", "DXF R12 (CUT and FOLD layers):");
  lines.push("Print it true size over several sheets (tiled PDF with alignment marks): " + page);
  return ok(lines.join("\n"), sc);
}

function hinge(a) {
  const unit = unitOf(a.unit), mat = H.MATERIALS[a.material] ? a.material : "plywood", f = unit === "in" ? 1 / 25.4 : 1;
  const d = (v, mm) => (num(v) !== undefined ? num(v) : r3(mm * f));
  const spec = { style: ["staggered", "wave", "lattice", "straight"].includes(a.style) ? a.style : "staggered", unit, width: d(a.width, 40), height: d(a.height, 100),
    cutLen: d(a.cut_length, 25), gap: d(a.gap, 4), pitch: d(a.pitch, 2), kerf: d(a.kerf, 0.15), slot: r3(1 * f), compensate: true, openEdges: true,
    material: mat, t: d(a.thickness, H.MATERIALS[mat].t), angle: num(a.angle) === undefined ? 90 : num(a.angle) };
  const p = H.pattern(spec);
  if (!p || !p.ok) return err("Could not make the hinge: " + ((p && p.error) || "check the inputs."));
  const u = unit, page = `${T}/living-hinge-generator/`, s = p.stats || {};
  const lines = [`**${spec.style === "straight" ? "Serpentine" : spec.style[0].toUpperCase() + spec.style.slice(1)} living hinge ${spec.width} × ${spec.height} ${u} in ${H.MATERIALS[mat].name} ${spec.t} ${u}:** ${s.cuts} cuts in ${p.cols} columns, ${r3(s.cutLength)} ${u} of cutting.`,
    `Estimated bend: up to about ${r3(p.maxAngle)}°${p.capped ? " (capped)" : ""}; minimum inside radius about ${r3(p.minRadius)} ${u}. For ${spec.angle}° the hinge needs about ${r3(p.neededWidth)} ${u} of width${p.neededWidth > spec.width ? " — wider than drawn" : ""}.`];
  if (p.warnings && p.warnings.length) lines.push("Note: " + p.warnings.join(" "));
  const sc = { style: spec.style, unit: u, material: mat, thickness: spec.t, width: spec.width, height: spec.height, cut_length: spec.cutLen, gap: spec.gap, pitch: spec.pitch, kerf: spec.kerf,
    cols: p.cols, stats: s, max_angle: p.maxAngle, capped: !!p.capped, min_radius: p.minRadius, needed_width: p.neededWidth, warnings: p.warnings || [], page };
  file(lines, sc, FMT(a.format, "svg"), () => p.svg({}), () => p.dxf(), "True-size SVG (red = cut lines):", "DXF R12 (CUT layer):");
  lines.push("The bend estimate is a torsion approximation with typical material values: test-cut a sample. Tune it visually: " + page);
  return ok(lines.join("\n"), sc);
}

const HANDLERS = { get_sheet_metal_gauge: gauge, calc_sheet_metal_bend: bendTool, make_cone_pattern: cone, make_living_hinge: hinge };
const NAMES = new Set(TOOL_DEFS.map((t) => t.name));
export function isTools63Tool(name) { return NAMES.has(name); }
export async function callTools63Tool(name, a) {
  a = a && typeof a === "object" ? a : {};
  try {
    if (HANDLERS[name]) return HANDLERS[name](a);
  } catch (e) {
    return err(`${name} failed: ${str(e && e.message, 300)}`);
  }
  return err("Unknown tool: " + name);
}
